 AcceptanceFixture(){shared->roles.find("sender")->services.push_back("information");tasks.personal_acceptances.emplace();for(auto& row:interaction.knowledge)row.offers.clear();ic.discoveries.push_back({"letter",{{"actor","sender",{}}}});catalog.offers.find("letter")->budget=7;auto policy=std::make_shared<TaskPersonalAcceptanceCatalog>();policy->policies.push_back({"original_acceptance","letter","private_sender_acceptance","accept"});catalog.personal_acceptances=policy;auto d=ic.dialogues.back();d.id="private_sender_acceptance";d.entry="accept";d.nodes.front().id="accept";d.nodes.front().text_key="sender_explicitly_hands_original_letter";ic.dialogues.push_back(d);known_catalog.templates.push_back({"private_sender_acceptance",d.id,{"installed_actor","player"},{"installed_actor","sender"}});}
